/**
 * Sanitizes input to prevent XSS attacks.
 * @param {string} str - The user-provided string.
 * @returns {string} - The sanitized string.
 */
function sanitize(str) {
    return str.replace(/[&<>'"`]/g, function (match) {
        const escape = {
            '&': '&amp;',
            '<': '&lt;',
            '>': '&gt;',
            '"': '&quot;',
            "'": '&#39;',
            '`': '&#96;'
        };
        return escape[match];
    });
}

module.exports = { sanitize };

